//! Seeded random patch generator + Correct Tune (ported from Randomizer.h).
//! Own PRNG (SplitMix64) so the same seed gives the same patch on every platform.
//! Float operations follow the C++ order exactly (no fused multiply-add) so patches match.

use crate::archetypes::{self, FIRST_ARCHETYPE_SEED};
use crate::params::idx::*;
use crate::params::*;

pub struct SplitMix { s: u64 }

impl SplitMix {
    pub fn new(seed: u64) -> Self { Self { s: seed } }
    pub fn next_u64(&mut self) -> u64 {
        self.s = self.s.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.s;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
        z ^ (z >> 31)
    }
    /// [0, 1)
    pub fn next(&mut self) -> f32 { (self.next_u64() >> 40) as f32 * (1.0f32 / 16777216.0f32) }
}

// ---- Correct Tune ----------------------------------------------------------------------------
/// Oscillator A is snapped to the nearest octave, oscillator B to the nearest perfect interval.
pub fn snap_to_octave(semitones: f32) -> f32 { (semitones / 12.0).round() * 12.0 }

pub fn snap_to_consonant(semitones: f32) -> f32 {
    const SET: [f32; 11] = [-24.0, -19.0, -12.0, -7.0, -5.0, 0.0, 5.0, 7.0, 12.0, 19.0, 24.0];
    let mut best = SET[0];
    for &s in SET.iter() {
        if (s - semitones).abs() < (best - semitones).abs() { best = s; }
    }
    best
}

pub fn correct_tune(values: &mut [f32]) {
    values[A_FREQ] = snap_to_octave(values[A_FREQ]);
    values[B_FREQ] = snap_to_consonant(values[B_FREQ]);
}

// ---- Randomize --------------------------------------------------------------------------------
fn clamp01(c: f32) -> f32 { if c < 0.0 { 0.0 } else if c > 1.0 { 1.0 } else { c } }

/// chaos 0 = soft and light, 1 = anything goes. Original generator (seeds below 1,000,000).
pub fn randomize_legacy(seed: u32, chaos: f32, out: &mut [f32]) {
    let chaos = clamp01(chaos);
    let mut rng = SplitMix::new((seed as u64).wrapping_mul(0x9E3779B1).wrapping_add(0x51ED270B));
    rng.next();

    for i in 0..NUM_PARAMS {
        let p = &PARAMS[i];
        let lo = p.soft_lo + (p.lo - p.soft_lo) * chaos;
        let hi = p.soft_hi + (p.hi - p.soft_hi) * chaos;

        let u1 = rng.next();
        let u2 = rng.next();
        let gate = rng.next();
        let tri = 0.5f32 * (u1 + u2);
        let u = tri + (u1 - tri) * chaos;
        let mut v = lo + (hi - lo) * u;

        if (p.flags & OFF_BIAS) != 0 && gate < 0.6f32 - 0.45f32 * chaos { v = p.def; }
        if (p.flags & STAR) != 0 && (p.flags & SEMITONE) == 0 { v = p.def + (v - p.def) * 0.5f32; }
        if (p.flags & STEP) != 0 { v = v.round(); }
        if (p.flags & NO_RANDOM) != 0 { v = p.def; }
        out[i] = if v < p.lo { p.lo } else if v > p.hi { p.hi } else { v };
    }
}

fn pick_bit(mask: u32, u: f32, count: usize) -> usize {
    let mut n = 0i32;
    for i in 0..count { if mask & (1u32 << i) != 0 { n += 1; } }
    if n == 0 { return 0; }
    let mut k = std::cmp::min(n - 1, (u * n as f32) as i32);
    for i in 0..count {
        if mask & (1u32 << i) != 0 {
            let hit = k == 0;
            k -= 1;
            if hit { return i; }
        }
    }
    0
}

/// Randomize v2 (seeds from 1,000,000): pick an archetype, then draw every knob from its ranges.
pub fn randomize_archetype(seed: u32, chaos: f32, out: &mut [f32]) {
    let chaos = clamp01(chaos);
    let a = &archetypes::LIST[archetypes::index_for_seed(seed)];

    let mut rng = SplitMix::new((seed as u64).wrapping_mul(0xD1B54A32D192ED03).wrapping_add(0xA5CE7E0DE5));
    rng.next();

    let u_src = rng.next();
    let u_rev = rng.next();
    let u_wild_src = rng.next();
    let u_wild_rev = rng.next();
    let u_wild_pick1 = rng.next();
    let u_wild_pick2 = rng.next();
    let mut src = pick_bit(a.src, u_src, NUM_SOURCES);
    let mut rev = pick_bit(a.rev, u_rev, NUM_REVERB_TYPES);
    if u_wild_src < 0.5f32 * chaos {
        src = std::cmp::min(NUM_SOURCES as i32 - 1, (u_wild_pick1 * NUM_SOURCES as f32) as i32) as usize;
    }
    if u_wild_rev < 0.6f32 * chaos {
        rev = std::cmp::min(NUM_REVERB_TYPES as i32 - 1, (u_wild_pick2 * NUM_REVERB_TYPES as f32) as i32) as usize;
    }

    for i in 0..NUM_PARAMS {
        let p = &PARAMS[i];
        let mut base_lo = p.soft_lo;
        let mut base_hi = p.soft_hi;
        let mut overridden = false;
        for o in a.ov.iter() {
            if o.p == i { base_lo = o.lo; base_hi = o.hi; overridden = true; break; }
        }
        let lo = base_lo + (p.lo - base_lo) * chaos;
        let hi = base_hi + (p.hi - base_hi) * chaos;

        let u1 = rng.next();
        let u2 = rng.next();
        let gate = rng.next();
        let tri = 0.5f32 * (u1 + u2);
        let u = tri + (u1 - tri) * chaos;
        let mut v = lo + (hi - lo) * u;

        if (p.flags & OFF_BIAS) != 0 && !overridden && gate < 0.6f32 - 0.45f32 * chaos { v = p.def; }
        if (p.flags & STAR) != 0 && (p.flags & SEMITONE) == 0 { v = p.def + (v - p.def) * 0.5f32; }
        if (p.flags & STEP) != 0 { v = v.round(); }
        if (p.flags & NO_RANDOM) != 0 { v = p.def; }
        out[i] = if v < p.lo { p.lo } else if v > p.hi { p.hi } else { v };
    }
    out[SRC_TYPE] = src as f32;
    out[RVB_TYPE] = rev as f32;
}

/// One entry point: the seed number says which generator grows the patch. `out` needs NUM_PARAMS slots.
pub fn randomize_values(seed: u32, chaos: f32, out: &mut [f32]) {
    if seed >= FIRST_ARCHETYPE_SEED {
        randomize_archetype(seed, chaos, out);
        return;
    }
    randomize_legacy(seed, chaos, out);
    out[SRC_TYPE] = 0.0; // older seeds keep the dual oscillator
}

/// Convenience: returns the patch as an array.
pub fn random_values(seed: u32, chaos: f32) -> [f32; NUM_PARAMS] {
    let mut v = [0.0f32; NUM_PARAMS];
    randomize_values(seed, chaos, &mut v);
    v
}

